// H 闸旁路封堵：名册员工（team.json 点了名的成员）的新派工必须声明 model——旧代码对「不带 model」
// 整段免检，「opus 领队没上场」恰恰可以借省略字段无声溜过。旧账本缺 model 只关读侧兼容（对账/折算），
// 不构成新写入放宽的理由，故名册员工缺 model 一律拒。非名册员工（如未选队的记账桶、走升档的临时工）
// 缺 model 照旧放行——它本就不在名册声明约束之列。跨档案读取（meta.json 拿团队名、team.json、
// team-config）只有 root 在手的这一层能做，schemas.mjs 的校验器保持纯函数、不碰文件系统。
async function assertDispatchModelDeclared(root, data) {
  // 特殊户头不受团队名册约束，也不强制声明 model：直接放行。
  if (DISPATCH_SPECIAL_EMPLOYEES.has(data.employee)) return;
  const hasModel = typeof data.model === 'string' && data.model.trim() !== '';
  // 读项目选定团队定义档：带了 model 要按它校验档位；缺 model 要按它判「是不是名册员工」。
  // 没选队（如纯记账测试桶）loadTeamDoc 会喊停——缺 model 且读不到团队＝压根不是任何名册的人，
  // 按读侧兼容放行，不无中生有喊停；带了 model 却没团队可校验则维持原行为、照旧喊停。
  let teamDoc;
  try {
    teamDoc = await loadTeamDoc(root);
  } catch (err) {
    if (hasModel) throw err;
    return;
  }
  if (!hasModel) {
    if (isTeamRosterMember(teamDoc, data.employee)) {
      throw new CliError(
        `名册员工「${data.employee}」派工缺 model（实际拉起的档位）：team.json 点名的成员新派工必须声明档位，` +
        '不许借省略 model 字段躲过模型声明核对（H 闸）'
      );
    }
    return;
  }
  const config = await readJson(root, WRITE_TYPES['team-config'].path());
  const allowed = resolveDispatchAllowedModels(teamDoc, data.employee, config);
  if (!allowed.includes(data.model)) {
    throw new CliError(
      `员工「${data.employee}」的实交档位「${data.model}」不是声明档：合法档位只有` +
      `${allowed.length > 0 ? allowed.join('、') : '（该员工未在团队名册声明模型，也没有升档/覆盖依据）'}` +
      '（团队声明档／升档档／项目覆盖档三选一），拒绝登记派工'
    );
  }
}

// L 项：write team-config 落盘前核对 member_models 的键都是团队名册里真实存在的成员——
// 档位是否在价目表内已在 schemas.mjs 的结构校验里查过，这里只补「人存在不存在」这半步
// （同样需要读项目当前选定的团队定义档，理由同上）。没写 member_models 的老写法不查。
async function assertTeamConfigMembersInTeam(root, data) {
  if (data.member_models === undefined) return;
  const teamDoc = await loadTeamDoc(root);
  assertMemberModelsExistInTeam(teamDoc, data.member_models);
}

// 落盘单笔写入（data 必须已过 validateOneWrite）：按类型声明的写入方式落盘，全部经 store
//（自动带指纹和事件流水）。抽出来给单写与批量共用；下面的 switch 与重构前一字不差
// （唯二例外：append-line 分支给 dispatch 补一道模型声明核对，overwrite 分支给 team-config
